// Parse a tree string and return the index after the matching closing parenthesis
// The string is of the form (left)[value](right) or empty
struct TreeNode {
    long long val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(long long v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* parseTree(const string& s, int& pos) {
    if (pos >= (int)s.size() || s[pos] != '(') {
        return nullptr;
    }
    // parse left child
    TreeNode* left = parseTree(s, pos);
    // now pos should be at '['
    if (pos >= (int)s.size() || s[pos] != '[') {
        // malformed, but assume valid input
        return nullptr;
    }
    // read value until ']'
    pos++; // skip '['
    long long val = 0;
    while (pos < (int)s.size() && s[pos] != ']') {
        val = val * 10 + (s[pos] - '0');
        pos++;
    }
    // skip ']'
    pos++;
    // parse right child
    TreeNode* right = parseTree(s, pos);
    // now pos should be at ')'
    if (pos < (int)s.size() && s[pos] == ')') {
        pos++; // skip ')'
    }
    TreeNode* node = new TreeNode(val);
    node->left = left;
    node->right = right;
    return node;
}

TreeNode* combine(TreeNode* t1, TreeNode* t2) {
    if (t1 == nullptr && t2 == nullptr) return nullptr;
    long long sum = (t1 ? t1->val : 0) + (t2 ? t2->val : 0);
    TreeNode* node = new TreeNode(sum);
    if (t1 && t2) {
        node->left = combine(t1->left, t2->left);
        node->right = combine(t1->right, t2->right);
    } else {
        node->left = nullptr;
        node->right = nullptr;
    }
    return node;
}

