                right = parse_tree(s, pos);
            }
            Node *node = (Node*)malloc(sizeof(Node));
            node->value = val;
            node->left = left;
            node->right = right;
            // expect ')'
            if (s[*pos] == ')') (*pos)++;
            return node;
        } else {
            // no value? shouldn't happen in valid input
            return NULL;
        }
    }
    return NULL;
}

Node* combine_trees(Node *t1, Node *t2) {
    if (t1 == NULL && t2 == NULL) return NULL;
