static void skip_spaces(const char **s) {
    while (**s && isspace((unsigned char)**s)) (*s)++;
}

static Node* parse_tree(const char **s);

static Node* new_node(long long v) {
    Node *n = (Node*)malloc(sizeof(Node));
    n->val = v;
    n->left = n->right = NULL;
    return n;
}

static Node* parse_tree(const char **s) {
    skip_spaces(s);
    if (**s != '(') return NULL;

    (*s)++; // '('
    skip_spaces(s);

    Node *left = NULL, *right = NULL;
    if (**s == '(') {
        left = parse_tree(s);
        skip_spaces(s);
    }

    if (**s != ')') return NULL;
    (*s)++; // ')'

    skip_spaces(s);
    if (**s != '[') return NULL;
    (*s)++; // '['

    skip_spaces(s);
    long long sign = 1, val = 0;
    if (**s == '-') { sign = -1; (*s)++; }
    while (**s && isdigit((unsigned char)**s)) {
        val = val * 10 + (**s - '0');
        (*s)++;
    }
    val *= sign;

    skip_spaces(s);
    if (**s != ']') return NULL;
    (*s)++; // ']'

    skip_spaces(s);
    if (**s != '(') return NULL;
    (*s)++; // '('
    skip_spaces(s);

    if (**s == '(') {
        right = parse_tree(s);
        skip_spaces(s);
    }

    if (**s != ')') return NULL;
    (*s)++; // ')'

    Node *root = new_node(val);
    root->left = left;
    root->right = right;
    return root;
}

static Node* merge_trees(Node *a, Node *b) {
    if (!a || !b) return NULL;
    Node *c = new_node(a->val + b->val);
    c->left = merge_trees(a->left, b->left);
    c->right = merge_trees(a->right, b->right);
    return c;
}

