static char* read_all_stdin(void) {
    size_t cap = 4096, len = 0;
    char *buf = (char*)malloc(cap);
    int ch;
    while ((ch = getchar()) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            buf = (char*)realloc(buf, cap);
        }
        buf[len++] = (char)ch;
    }
    buf[len] = '\0';
    return buf;
}

