public class Main {

    static int findClose(String s, int open, char openChar, char closeChar) {
        int depth = 0;
        for (int i = open; i < s.length(); i++) {
            if (s.charAt(i) == openChar) depth++;
            else if (s.charAt(i) == closeChar) {
                depth--;
                if (depth == 0) return i;
            }
        }
        return -1;
    }

    // Returns [leftContent, value, rightContent] as strings
    static String[] parse(String s) {
        // s = (left)[val](right)
        // starts with '('
        int leftClose = findClose(s, 0, '(', ')');
        String leftContent = s.substring(1, leftClose);
        // next is [val]
        int valOpen = leftClose + 1; // should be '['
        int valClose = s.indexOf(']', valOpen);
        String val = s.substring(valOpen + 1, valClose);
        // next is (right)
        int rightOpen = valClose + 1;
        int rightClose = findClose(s, rightOpen, '(', ')');
        String rightContent = s.substring(rightOpen + 1, rightClose);
        return new String[]{leftContent, val, rightContent};
    }

    static String combine(String t1, String t2) {
        if (t1.isEmpty() || t2.isEmpty()) return "";
        String[] p1 = parse(t1);
        String[] p2 = parse(t2);
        long val = Long.parseLong(p1[1]) + Long.parseLong(p2[1]);
        String newLeft = combine(p1[0], p2[0]);
        String newRight = combine(p1[2], p2[2]);
        return "(" + newLeft + ")[" + val + "](" + newRight + ")";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String t1 = sc.nextLine().trim();
        String t2 = sc.nextLine().trim();
        System.out.println(combine(t1, t2));
    }
}

