public class Main {
    static class Node {
        long val;
        Node left, right;
        Node(long v) { val = v; }
    }

    static class Parser {
        String s;
        int n, idx;

        Parser(String s) {
            this.s = s;
            this.n = s.length();
            this.idx = 0;
        }

        Node parseTree() {
            skipSpaces();
            if (idx >= n) return null;

            Node left = null, right = null;

            skipSpaces();
            if (idx < n && s.charAt(idx) == '(') {
                idx++; // '('
                int start = idx;
                int bal = 1;
                while (idx < n && bal > 0) {
                    char c = s.charAt(idx);
                    if (c == '(') bal++;
                    else if (c == ')') bal--;
                    idx++;
                }
                String inside = s.substring(start, idx - 1);
                if (!inside.trim().isEmpty()) {
                    left = new Parser(inside).parseTree();
                }
            }

            skipSpaces();
            if (idx >= n || s.charAt(idx) != '[') return null;
            idx++; // '['
            skipSpaces();
            long sign = 1;
            if (idx < n && s.charAt(idx) == '-') {
                sign = -1;
                idx++;
            }
            long val = 0;
            while (idx < n && Character.isDigit(s.charAt(idx))) {
                val = val * 10 + (s.charAt(idx) - '0');
                idx++;
            }
            val *= sign;
            skipSpaces();
            if (idx < n && s.charAt(idx) == ']') idx++;

            skipSpaces();
            if (idx < n && s.charAt(idx) == '(') {
                idx++; // '('
                int start = idx;
                int bal = 1;
                while (idx < n && bal > 0) {
                    char c = s.charAt(idx);
                    if (c == '(') bal++;
                    else if (c == ')') bal--;
                    idx++;
                }
                String inside = s.substring(start, idx - 1);
                if (!inside.trim().isEmpty()) {
                    right = new Parser(inside).parseTree();
                }
            }

            Node root = new Node(val);
            root.left = left;
            root.right = right;
            return root;
        }

        void skipSpaces() {
            while (idx < n && Character.isWhitespace(s.charAt(idx))) idx++;
        }
    }

    static Node merge(Node a, Node b) {
        if (a == null || b == null) return null;
        Node c = new Node(a.val + b.val);
        c.left = merge(a.left, b.left);
        c.right = merge(a.right, b.right);
        return c;
    }

    static String build(Node root) {
        if (root == null) return "";
        StringBuilder sb = new StringBuilder();
        sb.append('(').append(build(root.left)).append(')');
        sb.append('[').append(root.val).append(']');
        sb.append('(').append(build(root.right)).append(')');
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);

        String s1 = lines.size() > 0 ? lines.get(0).trim() : "";
        String s2 = lines.size() > 1 ? lines.get(1).trim() : "";

        Node t1 = s1.isEmpty() ? null : new Parser(s1).parseTree();
        Node t2 = s2.isEmpty() ? null : new Parser(s2).parseTree();

        Node merged = merge(t1, t2);
        System.out.println(build(merged));
    }
}

import sys
sys.setrecursionlimit(1_000_000)

class Node:
    __slots__ = ("val", "left", "right")
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def parse_tree(s: str):
    if not s:
        return None

    n = len(s)

    def parse(i):
        # parse left subtree: either empty or (...) starting at i
        left = None
        if i < n and s[i] == '(':
            depth = 1
            j = i + 1
            while j < n and depth:
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                j += 1
            inner = s[i + 1:j - 1]
            left = parse_tree(inner)
            i = j

        # parse [number]
        if i >= n or s[i] != '[':
            return None, i
        j = i + 1
        while j < n and s[j] != ']':
            j += 1
        val = int(s[i + 1:j])
        i = j + 1

        # parse right subtree: either empty or (...) starting at i
        right = None
        if i < n and s[i] == '(':
            depth = 1
            j = i + 1
            while j < n and depth:
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                j += 1
            inner = s[i + 1:j - 1]
            right = parse_tree(inner)
            i = j

        return Node(val, left, right), i

    root, _ = parse(0)
    return root

def merge(a, b):
    if a is None or b is None:
        return None
    return Node(
        a.val + b.val,
        merge(a.left, b.left),
        merge(a.right, b.right)
    )

def serialize(root):
    if root is None:
        return ""
    left = f"({serialize(root.left)})" if root.left is not None else ""
    right = f"({serialize(root.right)})" if root.right is not None else ""
    return f"{left}[{root.val}]{right}"

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    s1 = lines[0].strip() if len(lines) >= 1 else ""
    s2 = lines[1].strip() if len(lines) >= 2 else ""

    t1 = parse_tree(s1)
    t2 = parse_tree(s2)
    t3 = merge(t1, t2)
    print(serialize(t3))

